command:
$ErrorActionPreference = "Stop"
git fetch origin main --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch main failed" }
if ((git rev-parse origin/main).Trim() -ne "28b60642923cf3280f04b43c2322f50eea3b07b1") { throw "main moved" }

git -C $env:GITHUB_WORKSPACE push origin --delete work/search-v3-criteria
if ($LASTEXITCODE -ne 0) { throw "Search v3 work branch cleanup failed" }

Write-Host "SEARCH_V3_WORK_BRANCH_DELETED"
